import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { reservaService, ReservaResponse } from '../../services/api';
import { quartoService, QuartoResponse } from '../../services/api';
import { clienteService, ClienteResponse } from '../../services/api';
import { pagamentoService } from '../../services/api';
import { formatarDataBrasil } from '../../utils/dateUtils';
import ErrorModal from '../common/ErrorModal';

interface DashboardStats {
  totalReservas: number;
  reservasAtivas: number;
  reservasFinalizadas: number;
  reservasCanceladas: number;
  reservasHoje: number;
  totalQuartos: number;
  quartosDisponiveis: number;
  quartosOcupados: number;
  quartosManutencao: number;
  quartosSujo: number;
  totalClientes: number;
  clientesNovosMes: number;
  totalReceita: number;
  receitaMes: number;
  receitaHoje: number;
  ocupacaoAtual: number;
  ocupacaoMedia: number;
  ticketMedio: number;
  satisfacaoMedia: number;
}

interface RelatorioMensal {
  mes: string;
  reservas: number;
  receita: number;
  ocupacao: number;
  novosClientes: number;
}

interface AtividadeRecente {
  id: string;
  tipo: 'reserva' | 'checkin' | 'checkout' | 'pagamento' | 'cliente' | 'limpeza' | 'manutencao';
  descricao: string;
  data: Date;
  usuario?: string;
  status?: string;
}

const DashboardAdminUltra: React.FC = () => {
  const navigate = useNavigate();
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [relatorioMensal, setRelatorioMensal] = useState<RelatorioMensal[]>([]);
  const [atividadesRecentes, setAtividadesRecentes] = useState<AtividadeRecente[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [periodoRelatorio, setPeriodoRelatorio] = useState('6');
  const [showError, setShowError] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [selectedPeriod, setSelectedPeriod] = useState('mes');

  useEffect(() => {
    carregarDadosDashboard();
  }, [periodoRelatorio]);

  const carregarDadosDashboard = async () => {
    setIsLoading(true);
    try {
      let reservasData: any[] = [];
      let quartosData: any[] = [];
      let clientesData: any[] = [];
      let pagamentosData: any[] = [];

      reservasData = await reservaService.listarReservas();
      quartosData = await quartoService.listarQuartos();
      clientesData = await clienteService.listarClientes();
      pagamentosData = await pagamentoService.listarPagamentos();

      const hoje = new Date();
      const mesAtual = hoje.getMonth();
      const anoAtual = hoje.getFullYear();

      const totalReservas = reservasData.length || 0;
      const reservasAtivas = reservasData.filter((r: any) => r.status === 'ATIVA').length || 0;
      const reservasFinalizadas = reservasData.filter((r: any) => r.status === 'FINALIZADA').length || 0;
      const reservasCanceladas = reservasData.filter((r: any) => r.status === 'CANCELADA').length || 0;
      const reservasHoje = reservasData.filter((r: any) => {
        const dataReserva = new Date(r.createdAt || r.checkIn);
        return dataReserva.toDateString() === hoje.toDateString();
      }).length || 0;

      const totalQuartos = quartosData.length || 0;
      const quartosDisponiveis = quartosData.filter((q: any) => q.status === 'DISPONIVEL').length || 0;
      const quartosOcupados = quartosData.filter((q: any) => q.status === 'OCUPADO').length || 0;
      const quartosManutencao = quartosData.filter((q: any) => q.status === 'MANUTENCAO').length || 0;
      const quartosSujo = quartosData.filter((q: any) => q.status === 'SUJO').length || 0;

      const totalClientes = clientesData.length || 0;
      const clientesNovosMes = clientesData.filter((c: any) => {
        const dataCliente = new Date(c.createdAt);
        return dataCliente.getMonth() === mesAtual && dataCliente.getFullYear() === anoAtual;
      }).length || 0;

      const totalReceita = pagamentosData.reduce((acc: number, pgto: any) => {
        const valor = pgto.valor || pgto.valorTotal || 0;
        return acc + (typeof valor === 'number' ? valor : parseFloat(valor) || 0);
      }, 0);

      const receitaMes = pagamentosData
        .filter((pgto: any) => {
          const dataPgto = new Date(pgto.dataPagamento || pgto.createdAt);
          return dataPgto.getMonth() === mesAtual && dataPgto.getFullYear() === anoAtual;
        })
        .reduce((acc: number, pgto: any) => {
          const valor = pgto.valor || pgto.valorTotal || 0;
          return acc + (typeof valor === 'number' ? valor : parseFloat(valor) || 0);
        }, 0);

      const receitaHoje = pagamentosData
        .filter((pgto: any) => {
          const dataPgto = new Date(pgto.dataPagamento || pgto.createdAt);
          return dataPgto.toDateString() === hoje.toDateString();
        })
        .reduce((acc: number, pgto: any) => {
          const valor = pgto.valor || pgto.valorTotal || 0;
          return acc + (typeof valor === 'number' ? valor : parseFloat(valor) || 0);
        }, 0);

      const ocupacaoAtual = totalQuartos > 0 ? (quartosOcupados / totalQuartos) * 100 : 0;
      const ticketMedio = totalReservas > 0 ? totalReceita / totalReservas : 0;

      const diasNoMes = new Date(anoAtual, mesAtual + 1, 0).getDate();
      let totalOcupacaoDiaria = 0;
      for (let dia = 1; dia <= diasNoMes; dia++) {
        const dataDia = new Date(anoAtual, mesAtual, dia);
        const quartosOcupadosDia = reservasData.filter((r: any) => {
          const checkIn = new Date(r.checkIn);
          const checkOut = new Date(r.checkOut);
          return dataDia >= checkIn && dataDia < checkOut && r.status === 'ATIVA';
        }).length;
        totalOcupacaoDiaria += quartosOcupadosDia;
      }
      const ocupacaoMedia = totalQuartos > 0 ? (totalOcupacaoDiaria / (diasNoMes * totalQuartos)) * 100 : 0;

      setStats({
        totalReservas, reservasAtivas, reservasFinalizadas, reservasCanceladas, reservasHoje,
        totalQuartos, quartosDisponiveis, quartosOcupados, quartosManutencao, quartosSujo,
        totalClientes, clientesNovosMes, totalReceita, receitaMes, receitaHoje,
        ocupacaoAtual, ocupacaoMedia, ticketMedio, satisfacaoMedia: 4.5
      });

      gerarRelatorioMensalCompleto(reservasData, pagamentosData, clientesData, quartosData);

    } catch (error) {
      setErrorMessage('Não foi possível carregar os dados do dashboard. Tente novamente.');
      setShowError(true);
    } finally {
      setIsLoading(false);
    }
  };

  const gerarRelatorioMensalCompleto = (reservas: any[], pagamentos: any[], clientes: any[], quartos: any[]) => {
    try {
      const meses = [];
      const hoje = new Date();

      for (let i = parseInt(periodoRelatorio) - 1; i >= 0; i--) {
        const data = new Date(hoje.getFullYear(), hoje.getMonth() - i, 1);
        const mesNome = data.toLocaleDateString('pt-BR', { month: 'short', year: 'numeric' });

        const reservasMes = reservas.filter((r: any) => {
          const dataReserva = new Date(r.createdAt || r.checkIn);
          return dataReserva.getMonth() === data.getMonth() && 
                 dataReserva.getFullYear() === data.getFullYear();
        });

        const receitaMes = pagamentos
          .filter((pgto: any) => {
            const dataPgto = new Date(pgto.dataPagamento || pgto.createdAt);
            return dataPgto.getMonth() === data.getMonth() && 
                   dataPgto.getFullYear() === data.getFullYear();
          })
          .reduce((acc: number, pgto: any) => {
            const valor = pgto.valor || pgto.valorTotal || 0;
            return acc + (typeof valor === 'number' ? valor : parseFloat(valor) || 0);
          }, 0);

        const novosClientesMes = clientes.filter((c: any) => {
          const dataCliente = new Date(c.createdAt);
          return dataCliente.getMonth() === data.getMonth() && 
                 dataCliente.getFullYear() === data.getFullYear();
        }).length;

        const diasNoMes = new Date(data.getFullYear(), data.getMonth() + 1, 0).getDate();
        let totalOcupacaoDiaria = 0;

        for (let dia = 1; dia <= diasNoMes; dia++) {
          const dataDia = new Date(data.getFullYear(), data.getMonth(), dia);
          const quartosOcupadosDia = reservas.filter((r: any) => {
            const checkIn = new Date(r.checkIn);
            const checkOut = new Date(r.checkOut);
            return dataDia >= checkIn && dataDia < checkOut && r.status === 'ATIVA';
          }).length;
          totalOcupacaoDiaria += quartosOcupadosDia;
        }

        const ocupacaoMedia = quartos.length > 0 
          ? (totalOcupacaoDiaria / (diasNoMes * quartos.length)) * 100 
          : 0;

        meses.push({
          mes: mesNome,
          reservas: reservasMes.length,
          receita: receitaMes,
          ocupacao: Math.round(ocupacaoMedia * 10) / 10,
          novosClientes: novosClientesMes
        });
      }

      setRelatorioMensal(meses);
    } catch (error) {
      setRelatorioMensal([]);
    }
  };

  const formatarMoeda = (valor: number) => {
    return valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  const formatarDataHora = (data: Date) => {
    return data.toLocaleString('pt-BR', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const formatarTempo = (data: Date) => {
    const agora = new Date();
    const diff = agora.getTime() - data.getTime();
    const minutos = Math.floor(diff / 60000);
    const horas = Math.floor(diff / 3600000);
    const dias = Math.floor(diff / 86400000);

    if (minutos < 1) return 'Agora';
    if (minutos < 60) return `${minutos} min`;
    if (horas < 24) return `${horas} h`;
    return `${dias} d`;
  };

  const getAtividadeIcon = (tipo: string) => {
    switch (tipo) {
      case 'reserva': return '📝';
      case 'checkin': return '🏨';
      case 'checkout': return '🚪';
      case 'pagamento': return '💰';
      case 'cliente': return '👤';
      case 'limpeza': return '🧹';
      case 'manutencao': return '🔧';
      default: return '📊';
    }
  };

  const getAtividadeCor = (tipo: string) => {
    switch (tipo) {
      case 'reserva': return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200';
      case 'checkin': return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200';
      case 'checkout': return 'bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200';
      case 'pagamento': return 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900 dark:text-emerald-200';
      case 'cliente': return 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200';
      case 'limpeza': return 'bg-cyan-100 text-cyan-800 dark:bg-cyan-900 dark:text-cyan-200';
      case 'manutencao': return 'bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200';
      default: return 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200';
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-900 dark:to-slate-800 flex items-center justify-center">
        <div className="text-center">
          <div className="relative">
            <div className="animate-spin rounded-full h-16 w-16 border-4 border-slate-200 dark:border-slate-700 border-t-blue-600"></div>
            <div className="absolute inset-0 rounded-full h-16 w-16 border-4 border-transparent border-t-blue-400 animate-pulse"></div>
          </div>
          <p className="mt-6 text-lg font-medium text-slate-600 dark:text-slate-400">Carregando dashboard...</p>
        </div>
      </div>
    );
  }

  if (!stats) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-900 dark:to-slate-800 flex items-center justify-center">
        <div className="text-center">
          <div className="text-6xl mb-4">📊</div>
          <p className="text-lg text-slate-600 dark:text-slate-400">Não foi possível carregar os dados.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-900 dark:to-slate-800">
      {/* Sidebar */}
      <div className="w-64 bg-white dark:bg-slate-800 shadow-xl border-r border-slate-200 dark:border-slate-700 fixed left-0 top-0 h-full z-40">
        {/* Header Sidebar */}
        <div className="p-4 border-b border-slate-200 dark:border-slate-700">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-blue-600 rounded-lg flex items-center justify-center">
                <span className="text-white font-bold">H</span>
              </div>
              <div>
                <h2 className="text-lg font-bold text-slate-900 dark:text-white">Hotel Pro</h2>
                <p className="text-xs text-slate-500 dark:text-slate-400">Dashboard</p>
              </div>
            </div>
          </div>

          {/* Menu */}
          <nav className="p-4 space-y-2">
            <a href="/admin/dashboard" className="flex items-center space-x-3 px-3 py-2 rounded-lg bg-blue-50 dark:bg-blue-900 text-blue-700 dark:text-blue-300 font-medium">
              <span>📊</span>
              <span>Dashboard</span>
            </a>
            <a href="/admin/clientes" className="flex items-center space-x-3 px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 font-medium">
              <span>👥</span>
              <span>Clientes</span>
            </a>
            <a href="/admin/quartos" className="flex items-center space-x-3 px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 font-medium">
              <span>🏨</span>
              <span>Quartos</span>
            </a>
            <a href="/admin/funcionarios" className="flex items-center space-x-3 px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 font-medium">
              <span>👔�</span>
              <span>Funcionários</span>
            </a>
            <a href="/admin/relatorios" className="flex items-center space-x-3 px-3 py-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 font-medium">
              <span>📈</span>
              <span>Relatórios</span>
            </a>
          </nav>
        </div>
      </div>

      {/* Main Content */}
      <div className="ml-64">
        {/* Header */}
        <div className="bg-white dark:bg-slate-800 shadow-sm border-b border-slate-200 dark:border-slate-700">
          <div className="flex items-center justify-between px-6 py-4">
            <div className="flex items-center space-x-4">
              <div className="text-sm text-slate-500 dark:text-slate-400">Bem-vindo,</div>
              <div className="text-lg font-semibold text-slate-900 dark:text-white">Admin</div>
            </div>
            <div className="text-sm text-slate-500 dark:text-slate-400">
              {formatarDataHora(new Date())}
            </div>
            <div className="flex items-center space-x-4">
              <button className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors duration-200">
                <svg className="w-5 h-5 text-slate-600 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 17h5l-1.405-1.405A2.032 2.032 0 011-1-1h2a2.032 2.032 0 011 1 1v5m-4 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                </svg>
              </button>
            </div>
          </div>
        </div>

        {/* Content */}
        <div className="p-6">
          {/* KPI Cards */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
            <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg p-6 border border-slate-200 dark:border-slate-700">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center space-x-3">
                  <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-blue-600 rounded-lg flex items-center justify-center">
                      <span className="text-white text-lg">📊</span>
                  </div>
                  <div className="text-right">
                    <span className="text-xs font-medium text-green-600 dark:text-green-400">+12%</span>
                  </div>
                </div>
              </div>
              <div className="text-2xl font-bold text-slate-900 dark:text-white">{stats.totalReservas}</div>
              <p className="text-sm text-slate-600 dark:text-slate-400">Total Reservas</p>
              <div className="mt-4 flex items-center text-xs text-slate-500 dark:text-slate-400">
                <span className="w-2 h-2 bg-green-500 rounded-full mr-2"></span>
                {stats.reservasHoje} hoje
              </div>
            </div>

            <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg p-6 border border-slate-200 dark:border-slate-700">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center space-x-3">
                  <div className="w-10 h-10 bg-gradient-to-br from-emerald-500 to-emerald-600 rounded-lg flex items-center justify-center">
                      <span className="text-white text-lg">🏨</span>
                  </div>
                  <div className="text-right">
                    <span className="text-xs font-medium text-amber-600 dark:text-amber-400">+8%</span>
                  </div>
                </div>
              </div>
              <div className="text-2xl font-bold text-slate-900 dark:text-white">{stats.ocupacaoAtual.toFixed(1)}%</div>
              <p className="text-sm text-slate-600 dark:text-slate-400">Taxa Ocupação</p>
              <div className="mt-4 flex items-center text-xs text-slate-500 dark:text-slate-400">
                <span className="w-2 h-2 bg-amber-500 rounded-full mr-2"></span>
                Média: {stats.ocupacaoMedia.toFixed(1)}%
              </div>
            </div>

            <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg p-6 border border-slate-200 dark:border-slate-700">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center space-x-3">
                  <div className="w-10 h-10 bg-gradient-to-br from-amber-500 to-amber-600 rounded-lg flex items-center justify-center">
                      <span className="text-white text-lg">💰</span>
                  </div>
                  <div className="text-right">
                    <span className="text-xs font-medium text-green-600 dark:text-green-400">+23%</span>
                  </div>
                </div>
              </div>
              <div className="text-2xl font-bold text-slate-900 dark:text-white">{formatarMoeda(stats.totalReceita)}</div>
              <p className="text-sm text-slate-600 dark:text-slate-400">Receita Total</p>
              <div className="mt-4 flex items-center justify-between text-xs text-slate-500 dark:text-slate-400">
                <span className="flex items-center">
                  <span className="w-2 h-2 bg-green-500 rounded-full mr-2"></span>
                  {formatarMoeda(stats.receitaMes)} este mês
                </span>
                <span>{formatarMoeda(stats.receitaHoje)} hoje</span>
              </div>
            </div>

            <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg p-6 border border-slate-200 dark:border-slate-700">
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center space-x-3">
                  <div className="w-10 h-10 bg-gradient-to-br from-purple-500 to-purple-600 rounded-lg flex items-center justify-center">
                      <span className="text-white text-lg">👥</span>
                  </div>
                  <div className="text-right">
                    <span className="text-xs font-medium text-purple-600 dark:text-purple-400">+15%</span>
                  </div>
                </div>
              </div>
              <div className="text-2xl font-bold text-slate-900 dark:text-white">{stats.totalClientes}</div>
              <p className="text-sm text-slate-600 dark:text-slate-400">Total Clientes</p>
              <div className="mt-4 flex items-center text-xs text-slate-500 dark:text-slate-400">
                <span className="w-2 h-2 bg-green-500 rounded-full mr-2"></span>
                {stats.clientesNovosMes} novos este mês
              </div>
            </div>
          </div>

          {/* Gráfico Principal - Área */}
          <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg p-6 border border-slate-200 dark:border-slate-700 mb-8">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-slate-900 dark:text-white">Visão Geral de Desempenho</h2>
              <div className="flex items-center space-x-4">
                <button
                  onClick={() => setSelectedPeriod('dia')}
                  className={`px-3 py-1 rounded-lg text-sm font-medium ${
                    selectedPeriod === 'dia' 
                      ? 'bg-blue-600 text-white' 
                      : 'bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-300'
                  }`}
                >
                  Hoje
                </button>
                <button
                  onClick={() => setSelectedPeriod('semana')}
                  className={`px-3 py-1 rounded-lg text-sm font-medium ${
                    selectedPeriod === 'semana' 
                      ? 'bg-blue-600 text-white' 
                      : 'bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-300'
                  }`}
                >
                  Semana
                </button>
                <button
                  onClick={() => setSelectedPeriod('mes')}
                  className={`px-3 py-1 rounded-lg text-sm font-medium ${
                    selectedPeriod === 'mes' 
                      ? 'bg-blue-600 text-white' 
                      : 'bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-300'
                  }`}
                >
                  Mês
                </button>
              </div>
            </div>

            <div className="h-64 relative">
              <div className="absolute inset-0 flex items-end">
                {relatorioMensal.map((item, index) => {
                  const maxValue = Math.max(...relatorioMensal.map(r => Math.max(r.reservas, r.receita / 1000)));
                  const height = (item.reservas / maxValue) * 100;
                  const heightReceita = ((item.receita / 1000) / maxValue) * 100;

                  return (
                    <div key={index} className="flex-1 h-full mx-0.5">
                      <div className="relative h-full">
                        <div className="absolute bottom-0 w-full bg-blue-500 opacity-20 rounded-t-lg" style={{ height: `${height}%` }}></div>
                        <div className="absolute bottom-0 w-full bg-emerald-500 opacity-20 rounded-t-lg" style={{ height: `${heightReceita}%` }}></div>
                      </div>
                    </div>
                  );
                })}
              </div>
              <div className="absolute bottom-0 left-0 right-0 flex justify-around text-xs text-slate-500 dark:text-slate-400">
                {relatorioMensal.map((item, index) => (
                  <div key={index} className="text-center">
                    <div className="font-medium">{item.mes}</div>
                    <div className="flex space-x-4 justify-center">
                      <span className="text-blue-600">{item.reservas}</span>
                      <span className="text-emerald-600">{formatarMoeda(item.receita)}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Stats Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
            {/* Status dos Quartos */}
            <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg p-6 border border-slate-200 dark:border-slate-700">
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Status dos Quartos</h3>
              <div className="grid grid-cols-2 gap-4">
                <div className="text-center">
                  <div className="text-3xl font-bold text-green-600 dark:text-green-400">{stats.quartosDisponiveis}</div>
                  <p className="text-sm text-slate-600 dark:text-slate-400">Disponíveis</p>
                </div>
                <div className="text-center">
                  <div className="text-3xl font-bold text-red-600 dark:text-red-400">{stats.quartosOcupados}</div>
                  <p className="text-sm text-slate-600 dark:text-slate-400">Ocupados</p>
                </div>
                <div className="text-center">
                  <div className="text-3xl font-bold text-amber-600 dark:text-amber-400">{stats.quartosManutencao}</div>
                  <p className="text-sm text-slate-600 dark:text-slate-400">Manutenção</p>
                </div>
                <div className="text-center">
                  <div className="text-3xl font-bold text-cyan-600 dark:text-cyan-400">{stats.quartosSujo}</div>
                  <p className="text-sm text-slate-600 dark:text-slate-400">Para Limpeza</p>
                </div>
              </div>
            </div>

            {/* Métricas Adicionais */}
            <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg p-6 border border-slate-200 dark:border-slate-700">
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Métricas Adicionais</h3>
              <div className="grid grid-cols-2 gap-4">
                <div className="text-center">
                  <div className="text-2xl font-bold text-slate-900 dark:text-white">{stats.ticketMedio.toFixed(2)}</div>
                  <p className="text-sm text-slate-600 dark:text-slate-400">Ticket Médio</p>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-slate-900 dark:text-white">{stats.satisfacaoMedia.toFixed(1)}</div>
                  <div className="text-sm text-slate-600 dark:text-slate-400">Satisfação Média</div>
                </div>
              </div>
            </div>
          </div>

          {/* Atividades Recentes */}
          <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg p-6 border border-slate-200 dark:border-slate-700">
            <h2 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Atividades Recentes</h2>
            <div className="space-y-3">
              {[
                {
                  id: '1',
                  tipo: 'reserva' as const,
                  descricao: 'Nova reserva #123 - João Silva',
                  data: new Date('2026-01-30T10:30:00'),
                  usuario: 'João Silva',
                  status: 'ATIVA'
                },
                {
                  id: '2',
                  tipo: 'pagamento' as const,
                  descricao: 'Pagamento de R$ 500,00',
                  data: new Date('2026-01-30T14:20:00'),
                  usuario: 'Maria Santos'
                },
                {
                  id: '3',
                  tipo: 'cliente' as const,
                  descricao: 'Novo cliente: Pedro Costa',
                  data: new Date('2026-01-30T09:15:00'),
                  usuario: 'Pedro Costa'
                }
              ].map((atividade) => (
                <div key={atividade.id} className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-700 rounded-lg">
                  <div className="flex items-center space-x-3">
                    <span className="text-2xl">{getAtividadeIcon(atividade.tipo)}</span>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-slate-900 dark:text-white truncate">{atividade.descricao}</p>
                      <p className="text-xs text-slate-500 dark:text-slate-400">{formatarTempo(atividade.data)}</p>
                    </div>
                  </div>
                  <div className="flex items-center space-x-2">
                    <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${getAtividadeCor(atividade.tipo)}`}>
                      {atividade.status === 'completed' ? '✅' : getAtividadeIcon(atividade.tipo)}
                    </span>
                    <span className="text-xs text-slate-500 dark:text-slate-400">
                      {formatarTempo(atividade.data)}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Modal de Erro */}
          {showError && (
            <ErrorModal
              isOpen={showError}
              title="Erro"
              message={errorMessage}
              onClose={() => setShowError(false)}
            />
          )}
        </div>
      </div>
    </div>
  );
};

export default DashboardAdminUltra;
